For the purposes of this regression algorithm, I think we should have 2 valid risk management models here. I've modified the `MaximumDrawdownPercentPerSecurity` risk model to be inverted (take profit). You can copy this class into this algorithm file and use it as your second risk model. Be sure both risk models perform adjustments so we know both are being executed.
```csharp
/// <summary>
/// Provides an implementation of <see cref="IRiskManagementModel"/> that limits the unrealized profit
/// per holding to the specified percentage.
/// </summary>
public class MaximumUnrealizedProfitPercentPerSecurity : RiskManagementModel
{
    private readonly decimal _unrealizedProfitPercent;

    /// <summary>
    /// Initializes a new instance of the <see cref="MaximumDrawdownPercentPerSecurity"/> class
    /// </summary>
    /// <param name="unrealizedProfitPercent">The maximum percentage unrealized profit allowed for any single security holding, defaults to 5% unrealized profit per security</param>
    public MaximumUnrealizedProfitPercentPerSecurity(
        decimal unrealizedProfitPercent = 0.05m
        )
    {
        _unrealizedProfitPercent = Math.Abs(unrealizedProfitPercent);
    }

    /// <summary>
    /// Manages the algorithm's risk at each time step
    /// </summary>
    /// <param name="algorithm">The algorithm instance</param>
    /// <param name="targets">The current portfolio targets to be assessed for risk</param>
    public override IEnumerable<IPortfolioTarget> ManageRisk(QCAlgorithmFramework algorithm, IPortfolioTarget[] targets)
    {
        foreach (var kvp in algorithm.Securities)
        {
            var security = kvp.Value;

            if (!security.Invested)
            {
                continue;
            }

            var pnl = security.Holdings.UnrealizedProfitPercent;
            if (pnl > _unrealizedProfitPercent)
            {
                // liquidate/take profit
                yield return new PortfolioTarget(security.Symbol, 0);
            }
        }
    }
}
